"use client";

import { useMemo, useState } from "react";
import type { Session } from "next-auth";

import { MailSidebar } from "./MailSidebar";
import { MailList } from "./MailList";
import { MailDetail } from "./MailDetail";
import {
  MOCK_MAIL_ITEMS,
  type MailItem,
  type MailLabel,
} from "../types/mail";

type MailAppProps = {
  session: Session;
};

type ViewMode = "list" | "detail";

export function MailApp({ session }: MailAppProps) {
  const [activeLabel, setActiveLabel] = useState<MailLabel>("INBOX");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const [viewMode, setViewMode] = useState<ViewMode>("list");
  const [isSidebarOpen, setIsSidebarOpen] = useState(true); // NEW

  const filteredEmails = useMemo(() => {
    return MOCK_MAIL_ITEMS.filter((mail) => {
      if (activeLabel === "INBOX" && mail.label !== "INBOX") return false;
      if (activeLabel !== "INBOX" && mail.label !== activeLabel) return false;

      const q = search.toLowerCase();
      if (!q) return true;

      return (
        mail.subject.toLowerCase().includes(q) ||
        mail.from.toLowerCase().includes(q) ||
        mail.snippet.toLowerCase().includes(q)
      );
    });
  }, [activeLabel, search]);

  const selectedMail: MailItem | null =
    filteredEmails.find((m) => m.id === selectedId) ?? null;

  const unreadInboxCount = useMemo(
    () =>
      MOCK_MAIL_ITEMS.filter(
        (m) => m.label === "INBOX" && m.unread,
      ).length,
    [],
  );

  return (
    <div className="flex h-screen flex-col bg-[#f6f8fc] text-slate-900">
      {/* Top app bar */}
      <header className="flex h-14 items-center gap-4 bg-[#f6f8fc] px-4">
        {/* Left: logo */}
        <div className="flex items-center gap-2">
          <div className="flex h-8 w-8 items-center justify-center rounded-full bg-[#1a73e8] text-sm font-semibold text-white">
            M
          </div>
          <span className="text-lg font-medium tracking-tight">Mail</span>
        </div>

        {/* Search bar (center like Gmail) */}
        <div className="mx-auto flex max-w-xl flex-1 items-center">
          <div className="flex w-full items-center rounded-full bg-[#eaf1fb] px-4 py-2 text-sm text-slate-700 shadow-inner">
            <span className="mr-2 text-slate-500">🔍</span>
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search mail"
              className="w-full bg-transparent text-sm outline-none placeholder:text-slate-500"
            />
          </div>
        </div>

        {/* Right side user / sign out */}
        <div className="flex items-center gap-3">
          <span className="hidden max-w-[180px] truncate text-xs text-slate-600 sm:inline-block">
            {session.user?.email ?? session.user?.name ?? "Signed in"}
          </span>
          <a
            href="/api/auth/signout"
            className="rounded-full border border-slate-300 px-3 py-1.5 text-xs font-medium text-slate-700 hover:bg-slate-100"
          >
            Sign out
          </a>
        </div>
      </header>

      {/* Main layout: icon rail + sidebar + (list OR detail) */}
      <div className="flex flex-1 overflow-hidden">
        {/* LEFT ICON RAIL (like Gmail’s Mail / Chat / Meet column) */}
        <div className="flex h-full w-14 flex-col items-center bg-[#f6f8fc] pt-2">
          {/* Hamburger / menu button */}
          <button
            type="button"
            onClick={() => setIsSidebarOpen((prev) => !prev)}
            className="mb-4 rounded-full p-2 text-slate-600 hover:bg-[#e8eaed]"
            aria-label="Toggle sidebar"
          >
            {/* cheap menu icon; you can replace with Material Symbols later */}
            <span className="block text-xl leading-none">☰</span>
          </button>

          {/* Main app icon (Mail) */}
          <button
            type="button"
            className="mt-1 flex h-10 w-10 items-center justify-center rounded-full bg-[#c2e7ff] text-sm font-medium text-[#0b57d0] shadow-sm"
          >
            M
          </button>

          {/* Spacer for future icons (Chat / Meet, etc.) */}
          <div className="mt-4 flex flex-1 flex-col items-center gap-3 text-xs text-slate-500">
            {/* placeholders – you can add more icons here later */}
          </div>
        </div>

        {/* Full labels sidebar (Inbox / Starred / …) */}
        {isSidebarOpen && (
          <MailSidebar
            activeLabel={activeLabel}
            unreadInboxCount={unreadInboxCount}
            onLabelChange={(label) => {
              setActiveLabel(label);
              setViewMode("list");
              setSelectedId(null);
            }}
          />
        )}

        {/* Center content area – Gmail-style card sits inside here */}
        <div className="flex flex-1 overflow-hidden px-4 pt-3 pb-4">
          {viewMode === "list" && (
            <MailList
              emails={filteredEmails}
              selectedId={selectedId}
              onSelect={(id) => {
                setSelectedId(id);
                setViewMode("detail");
              }}
            />
          )}

          {viewMode === "detail" && (
            <MailDetail
              email={selectedMail}
              onBack={() => setViewMode("list")}
            />
          )}
        </div>
      </div>
    </div>
  );
}
